acquisition-function.pseudocode:
def ucb(mu, sigma, kappa=2.0):
    return mu + kappa * sigma  # κ 클수록 탐색 강화

def expected_improvement(mu, sigma, best, xi=0.01):
    # 최대화 기준: 현재 최고값 best 대비 기대 개선량
    if sigma == 0:
        return 0.0
    imp = mu - best - xi
    z = imp / sigma
    return imp * norm_cdf(z) + sigma * norm_pdf(z)

def next_point(candidates, model, best):
    scores = []
    for x in candidates:
        mu, sigma = model.predict(x)  # 대리 모델 예측
        scores.append(expected_improvement(mu, sigma, best))
    return candidates[argmax(scores)]  # 다음 평가 지점

action-table.pseudocode:
def lr_parse(tokens, ACTION, GOTO, rules):
    stack = [0]  # 상태 스택 (시작 상태 0)
    tokens = tokens + ['$']
    i = 0
    while True:
        s, a = stack[-1], tokens[i]
        act = ACTION.get((s, a))
        if act is None:
            return 'error'  # 빈칸 = 구문 오류
        kind, val = act
        if kind == 'shift':
            stack.append(val)  # 다음 상태 push, 입력 전진
            i += 1
        elif kind == 'reduce':
            lhs, rhs_len = rules[val]  # 규칙 A → β
            for _ in range(rhs_len):
                stack.pop()  # β 길이만큼 상태 pop
            stack.append(GOTO[(stack[-1], lhs)])
        elif kind == 'accept':
            return 'accept'

actor-model.pseudocode:
class Actor:
    def __init__(self):
        self.mailbox = Queue()
        self.state = {}  # 외부에 공유되지 않는 상태

    def send(self, msg):  # 비동기: 넣고 즉시 반환
        self.mailbox.put(msg)

    def run(self):  # 메시지를 하나씩 순차 처리
        while True:
            msg = self.mailbox.get()
            self.receive(msg)  # 상태 변경은 이 액터만 → 락 불필요

class Counter(Actor):
    def receive(self, msg):
        if msg.kind == 'inc':
            self.state['n'] = self.state.get('n', 0) + 1
        elif msg.kind == 'get':  # 응답도 메시지로
            msg.reply_to.send(self.state.get('n', 0))
